#[using="Type"] Lemma rmrep_shadow_byte st m rid r o v :
rmrep st m -> (s_regions st) !! rid = Some r -> r_kind r = RKGroup ->
0 <= o < round_up_pg (r_len r) -> cell_read (get_shadow st rid) o = Known v ->
bytes_at segs m (r_base r + o) [b8 v] /\ 0 <= v < 256.
Proof. clear - segs st m rid r o v.
intros (WF & _ & _ & _ & _ & SH) Hr Hk Ho Hc.
destruct (SH rid r Hr Hk) as [HW HB]. exact (HB o v Ho Hc).
Qed.

#[using="base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry"] Lemma byte_of_eq v k : 0 <= k -> byte_of v k = (v / 2 ^ (8 * k)) mod 256.
Proof. clear - base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry v k. intros Hk. unfold byte_of. change 255 with (Z.ones 8). rewrite Z.land_ones, Z.shiftr_div_pow2 by klia. reflexivity. Qed.

#[using="base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry"] Lemma le4_byte_of v : 0 <= v < 2^32 -> le4 (wz v) = [b8 (byte_of v 0); b8 (byte_of v 1); b8 (byte_of v 2); b8 (byte_of v 3)].
Proof. clear - base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry v.
intros Hv. rewrite le4_bytes by klia. rewrite !byte_of_eq by klia.
change (2 ^ (8 * 0)) with 1. change (2 ^ (8 * 1)) with 256. change (2 ^ (8 * 2)) with 65536. change (2 ^ (8 * 3)) with 16777216.
rewrite Z.div_1_r. rewrite (Z.mod_small (v / 16777216)) by (Z.div_mod_to_equations; klia). reflexivity.
Qed.

#[using="Type"] Lemma bytes_at_cons m a x bs : bytes_at segs m a [x] -> bytes_at segs m (a + 1) bs -> bytes_at segs m a (x :: bs).
Proof. clear - segs m a x bs. intros H1 H2. apply (proj2 (bytes_at_app segs m a [x] bs)). split; [gw_exact H1| gw_exact H2]. Qed.

Definition rr_mremap_tree (cs : mstate) (slot : cptr) (off n : Z) (g : aptr) : QUZl.M (mstate * option rr_where) :=
let mr := get_meta_rec cs g in
guard 70 (m_sizeclass mr =? 63) (
match m_mem mr with
| None => SVis (EUndef UBadPtr) (fun _ => ret (cs, @None rr_where))
| Some gmem =>
let needed := rr_needed n (UNIT * off) in
let oldlen := m_maplen mr * 4096 in
let rid := fst gmem in
if oldlen =? needed then ret (cs, Some RRSame)
else if PTRDIFF_MAX <=? needed then rr_general cs slot n
else
SVis (EMremap (conc cs gmem) oldlen needed MREMAP_MAYMOVE) (fun r =>
if negb (mremap_answer_ok (live_ranges cs) (conc cs gmem) oldlen needed r) then bad_answer (ret (cs, @None rr_where))
else if is_err r then rr_general cs slot n
else ret (strip (remap_region rid r needed g cs), Some RRSame))
end) (ret (cs, @None rr_where)).

#[using="Type"] Lemma crealloc_cases cs slot off n g idx :
(s_slots cs) !! slot = Some (g, idx) -> size_overflows n = false ->
crealloc cs slot off n =
let mr := get_meta_rec cs g in
if cond_inplace n (get_stride mr - IB - UNIT * off) (m_sizeclass mr) then ret (cs, Some RRSame)
else if cond_mremap n (m_sizeclass mr) then rr_mremap_tree cs slot off n g
else rr_general cs slot n.
Proof. clear - cs slot off n g idx. intros Hs Ho. unfold crealloc. rewrite Hs, Ho. reflexivity. Qed.

#[using="base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry"] Lemma size_overflows_small n : 0 <= n < 2^32 -> size_overflows n = false.
Proof. clear - base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry n. intros Hn. unfold size_overflows. apply Z.leb_gt. klia. Qed.

#[using="Type"] Lemma ctx_havoc p n st : ctx (havoc p n st) = ctx st.
Proof. clear - p n st. unfold havoc. destruct (n <=? 0); reflexivity. Qed.
#[using="Type"] Lemma ctx_set_size p e n b st : ctx (set_size p e n b st) = ctx st.
Proof. clear - p e n b st. unfold set_size. destruct (5 <=? _); destruct (negb _); reflexivity. Qed.
#[using="Type"] Lemma brk_link_ext st st' pb : ctx st' = ctx st -> (forall q, conc st' q = conc st q) -> brk_link st pb -> brk_link st' pb.
Proof. clear - st st' pb. intros E C H. unfold brk_link in *. rewrite E. destruct (c_brk (ctx st)); try gw_exact H. rewrite C. gw_exact H. Qed.

#[using="base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry"] Lemma bytes_at_prefix_eq m a l1 l2 :
bytes_at segs m a l1 -> bytes_at segs m a l2 -> (length l1 <= length l2)%nat -> firstn (length l1) l2 = l1.
Proof. clear - base rvm_wait_entry rfree_entry rmalloc_entry rrealloc_sym rmremap_entry segs m a l1 l2.
intros (_ & _ & H1) (_ & _ & H2) L.
apply nth_error_ext. intros k. rewrite nth_error_firstn. destruct (Nat.ltb_spec k (length l1)) as [Hk|Hk].
- rewrite <- H1, <- H2 by klia. reflexivity.
- symmetry. apply nth_error_None. klia.
Qed.

#[using="Type"] Lemma rheap_pres_of_rpres LB SP C m m' :
rpres_except C m m' -> (forall a, 0 <= a < 2^64 -> rclient_addr LB SP a -> ~ C a) -> rheap_pres LB SP m m'.
Proof. clear - LB SP C m m'. intros HP HC a Ha Hc. apply HP; [gw_exact Ha| exact (HC a Ha Hc)]. Qed.

#[using="Type"] Lemma bytes_at_mext m m' a bs : (forall x, m' x = m x) -> bytes_at segs m a bs -> bytes_at segs m' a bs.
Proof. clear - segs m m' a bs. intros E (H0 & H1 & H). split; [gw_exact H0|]. split; [gw_exact H1|]. intros i Hi. unfold mrd. rewrite E. apply H. gw_exact Hi. Qed.

#[using="Type"] Lemma munch_of_mext W m m' : (forall x, m' x = m x) -> munch W m m'.
Proof. clear - W m m'. intros E x _. apply E. Qed.

#[using="Type"] Lemma wmono_of_mext m m' : (forall x, m' x = m x) -> wmono segs m m'.
Proof. clear - segs m m'. intros E x. unfold wview. rewrite E. exact (fun H => H). Qed.

#[using="Type"] Lemma mem_inv_mext m m' : (forall x, m' x = m x) -> mem_inv segs m -> mem_inv segs m'.
Proof. clear - segs m m'. intros E H a b Ha. rewrite E in Ha. exact (H a b Ha). Qed.

